import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/moran_local_2022_waste.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
data['Waste_value'] = data['Waste_value'].fillna(data['Waste_value'].mean())

# Compute neighborhood statistics
neighborhood_stats = {}
for index, row in data.iterrows():
    neighbors = adjacency[adjacency['borough'] == row['borough']]
    neighborhood_stats[row['borough']] = np.mean(neighbors['neighbor'].map(data['Waste_value']))

# Classify boroughs
classifications = {}
for index, row in data.iterrows():
    neighbors = adjacency[adjacency['borough'] == row['borough']]
    avg_neighbor_waste = np.mean(neighbors['neighbor'].map(data['Waste_value']))
    if row['Waste_value'] > avg_neighbor_waste:
        classifications[row['borough']] = 'HOT SPOT'
    elif row['Waste_value'] < avg_neighbor_waste:
        classifications[row['borough']] = 'COLD SPOT'
    else:
        classifications[row['borough']] = 'NEIGHBORHOOD AVERAGE'

# Compute statistical significance
significance = {}
for borough, classification in classifications.items():
    neighbors = adjacency[adjacency['borough'] == borough]
    avg_neighbor_waste = np.mean(neighbors['neighbor'].map(data['Waste_value']))
    test_statistic = np.abs(row['Waste_value'] - avg_neighbor_waste)
    p_value = np.mean([np.abs(np.random.choice(data['Waste_value'], size=len(data)) - avg_neighbor_waste) 
                      for _ in range(500)]) / 500
    significance[borough] = (test_statistic, p_value)

# Identify qualifying boroughs
qualifying_boroughs = []
for borough, classification in classifications.items():
    if classification in ['HOT SPOT', 'COLD SPOT']:
        qualifying_boroughs.append((borough, classification, significance[borough]))

# Print the results
print(f'data_points_used = {len(data)}')
for borough, classification, significance in qualifying_boroughs:
    print(f'FINAL ANSWER: {borough} ({classification}, test statistic = {significance[0]}, significance measure = {significance[1]})')

# Print the list of qualifying boroughs
if qualifying_boroughs:
    print(' '.join([f'{borough} ({classification[0]})' for borough, classification in qualifying_boroughs]))
else:
    print('FINAL ANSWER: none')
